text.sanRoadSeeds445:
function sanRoadSeeds445(rootIdx){
  const out=[];if(rootIdx<0||rootIdx>=N*N)return out;const b=tiles[rootIdx]&&tiles[rootIdx].bld;if(!b||b.ref)return out;
  const rx=rootIdx%N,ry=(rootIdx/N)|0,sz=Math.max(1,b.sz||1);
  for(let fy=0;fy<sz;fy++)for(let fx=0;fx<sz;fx++)for(const[dx,dy]of DIRV){
    const nx=rx+fx+dx,ny=ry+fy+dy;if(!inMap(nx,ny))continue;const j=idx(nx,ny);if(!tiles[j].road||out.includes(j))continue;out.push(j);
  }
  return out;
}

text.countNear:
function countNear(x,y,r,pred){
  let n=0;
  for(let dy=-r;dy<=r;dy++)for(let dx=-r;dx<=r;dx++){
    const nx=x+dx,ny=y+dy;
    if(!inMap(nx,ny))continue;
    if(pred(T(idx(nx,ny))))n++;
  }
  return n;
}

text.logisticsOperational485:
function logisticsOperational485(rootIdx,b){if(assetAvailability493(rootIdx,'logistics')<=.02)return false;
  if(!b||b.ref||!LOGISTICS_META485[b.k]||!b.pw)return false;
  if(!sanRoadSeeds445(rootIdx).length)return false; // 物流設施必須真正貼到道路 frontage
  const x=rootIdx%N,y=(rootIdx/N)|0;
  if(b.k===166&&countNear(x,y,6,t=>t.rail)<2)return false;
  if(b.k===173&&countNear(x,y,5,t=>t.t===0)<4)return false;
  if(b.k===174&&countNear(x,y,6,t=>t.t===0)<5)return false;
  return true;
}
